const { createHash, createHmac, timingSafeEqual } = require('crypto');

const maxClockSkewSeconds = 300;
const receiptLifetimeMs = 24 * 60 * 60 * 1000;
const maxReceipts = 10000;
const expectedStatus = {
  'request.created': 'pending',
  'request.approved': 'approved',
  'request.declined': 'declined',
  'request.returned': 'returned',
};

function respond(statusCode, body) {
  return [{ json: { statusCode, body } }];
}

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is missing');
}

const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];
const now = Date.now();
if (typeof timestamp !== 'string' || !/^\d{10}$/.test(timestamp)
    || typeof signature !== 'string' || !/^[a-f0-9]{64}$/.test(signature)
    || Math.abs(Math.floor(now / 1000) - Number(timestamp)) > maxClockSkewSeconds) {
  return respond(401, { ok: false, error: 'Invalid webhook signature' });
}

const binary = item.binary?.data;
if (!binary) {
  return respond(400, { ok: false, error: 'Raw request body is required' });
}
const rawBody = binary.id
  ? await this.helpers.getBinaryDataBuffer(0, 'data')
  : Buffer.from(binary.data, 'base64');
if (rawBody.length > 16 * 1024) {
  return respond(413, { ok: false, error: 'Payload too large' });
}

const expected = createHmac('sha256', secret)
  .update(timestamp + '.', 'utf8')
  .update(rawBody)
  .digest();
if (!timingSafeEqual(Buffer.from(signature, 'hex'), expected)) {
  return respond(401, { ok: false, error: 'Invalid webhook signature' });
}

let payload;
try {
  payload = JSON.parse(rawBody.toString('utf8'));
} catch {
  return respond(400, { ok: false, error: 'Invalid JSON payload' });
}
if (!payload || Array.isArray(payload) || typeof payload !== 'object'
    || !Object.prototype.hasOwnProperty.call(expectedStatus, payload.event)
    || payload.status !== expectedStatus[payload.event]
    || !['eventId', 'loanId', 'recipientRef', 'toolName'].every((key) =>
      typeof payload[key] === 'string' && payload[key].trim().length > 0)
    || ![payload.startDate, payload.endDate].every((date) =>
      typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date))) {
  return respond(400, { ok: false, error: 'Invalid event payload' });
}

const eventKey = createHash('sha256').update(payload.eventId).digest('hex');
const state = $getWorkflowStaticData('global');
const receipts = state.requestReceipts ??= {};
for (const [key, receivedAt] of Object.entries(receipts)) {
  if (receivedAt < now - receiptLifetimeMs) delete receipts[key];
}
if (Object.prototype.hasOwnProperty.call(receipts, eventKey)) {
  return respond(200, { ok: true, duplicate: true });
}
if (Object.keys(receipts).length >= maxReceipts) {
  console.error('[lendloop] request receipt capacity exhausted');
  return respond(503, { ok: false, error: 'Receipt store temporarily unavailable' });
}

// Mock delivery deliberately omits the recipient, loan data and free-text tool name.
receipts[eventKey] = now;
console.log('[lendloop] ' + JSON.stringify({
  delivery: 'mock',
  notification: payload.event,
  reference: eventKey.slice(0, 16),
}));
return respond(200, { ok: true, duplicate: false, delivery: 'mock', notification: payload.event });
